 venue='' if kind=='misc' else f'  booktitle={{{p["bibvenue"]}}},\n'
 note='  note={Author-provided manuscript; publication identifiers omitted},\n' if kind=='misc' else ''
 p['bibtex']=f'@{kind}{{kim{p["year"]}{p["slug"].replace("-","")},\n  title={{{p["formal_title"]}}},\n  author={{{p["bibauthors"]}}},\n{venue}{note}  year={{{p["year"]}}}\n}}'
 if p['slug']=='star':p['bibtex']=p['bibtex'].replace('kim2026star','sung2026star')
